<div class="admin-dashboard-grid user-management-grid"><section class="admin-panel"><div class="admin-panel-heading"><div><p class="eyebrow">AKUN CMS</p><h2>Daftar pengguna</h2></div><span class="table-count"><?= count($users) ?> akun</span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Nama & email</th><th>Peran</th><th>Status</th><th>Login terakhir</th><th>Aksi</th></tr></thead><tbody><?php foreach ($users as $account): ?><tr><td><strong><?= e($account['name']) ?></strong><small><?= e($account['email']) ?></small></td><td><?= e(str_replace('_',' ',$account['role'])) ?></td><td><span class="status-pill <?= (int)$account['is_active'] ? 'status-published' : 'status-archived' ?>"><?= (int)$account['is_active'] ? 'Aktif' : 'Nonaktif' ?></span></td><td><?= e($account['last_login_at'] ? format_date($account['last_login_at'], true) : 'Belum pernah') ?></td><td><?php if ((int)$account['id'] !== (int)$user['id']): ?><form method="post" action="/admin/pengguna/<?= (int)$account['id'] ?>/status" data-confirm="Ubah status akun ini?"><?= csrf_field() ?><button type="submit"><?= (int)$account['is_active'] ? 'Nonaktifkan' : 'Aktifkan' ?></button></form><?php else: ?><small>Akun Anda</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-panel"><div class="admin-panel-heading"><div><p class="eyebrow">PENGGUNA BARU</p><h2>Tambah akun</h2></div></div><form method="post" action="/admin/pengguna" class="form-stack"><?= csrf_field() ?><label>Nama pengguna<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Peran<select name="role"><option value="editor">Editor / Redaksi</option><option value="operator">Operator</option><option value="viewer">Pembaca</option><option value="super_admin">Super Admin</option></select></label><label>Kata sandi awal<input type="password" name="password" minlength="12" required><small>Minimal 12 karakter. Berikan kata sandi melalui kanal yang aman.</small></label><button class="button button-primary button-wide" type="submit">Buat akun</button></form></section></div>
<div class="admin-note"><strong>Ringkasan hak akses:</strong><span>Super Admin mengelola seluruh sistem; Editor mengelola dan menghapus konten; Operator membuat serta memperbarui konten dan media; Pembaca hanya melihat data CMS.</span></div>
